# The Listing Duration tabs' UI (step 7 slice 2a, 2026-11-21): both states' app.R had these two nav_panels
# identical. Generated by Jobs_Dash_repos claude-notes/2026-11-21_step7-slice1/make_ui_spells.R from main's app.R;
# changes: calls written pkg::fn(). Their server side is in dashboard_server_shared().

#' K-12 Listing Duration tab
#'
#' The `nav_panel()` for K-12 > Listing Duration (value `"k12_spells"`).
#' @export
k12_spells_panel <- function() {
  need_shiny_ui("k12_spells_panel")
  bslib::nav_panel(
    "Listing Duration", value = "k12_spells", icon = shiny::icon("stopwatch"),
    htmltools::h3(class = "page-title", htmltools::tagList(shiny::icon("stopwatch"), " K-12 Listing Duration")),
    htmltools::p(class = "text-muted small",
      "How long each K-12 posting stayed listed on the job boards this dashboard tracks."),
    bslib::layout_sidebar(
      fillable = FALSE,
      class = "page-sidebar",
      sidebar = bslib::sidebar(
        title = "Filters",
        width = 260,
        shiny::selectInput("k12_spell_status", "Listing status:",
                    choices = c("All Postings" = "all",
                                "Still Active (Open)" = "Still Active",
                                "No longer listed" = "No longer listed"),
                    selected = "all"),
        shiny::selectInput("k12_spell_position", "Position group:",
                    choices = c("All Roles" = "all",
                                "Teacher" = "Teacher",
                                "Administration" = "Administration",
                                "Support Staff / Classified" = "Support"),
                    selected = "all"),
        shiny::selectInput("k12_spell_discipline", "Discipline / shortage area:",
                    choices = c("All Disciplines" = "all",
                                "STEM (Math & Science)" = "stem",
                                "Special Education" = "sped",
                                "Elementary Education" = "elementary",
                                "Secondary Education" = "secondary",
                                "Administration" = "admin",
                                "Support / Classified" = "support"),
                    selected = "all"),
        shiny::selectInput("k12_spell_district", "District:",
                    choices = c("All Districts" = "all"),
                    selected = "all")
      ),
      # Duration KPI boxes and charts left out (spells_footnote()); their
      # server outputs are kept.
      bslib::card(
        bslib::card_header(
          class = "d-flex justify-content-between align-items-center",
          "Postings and how long they stayed listed",
          info_popover(
            "How days listed is counted",
            htmltools::p(class = "mb-0", "Days listed = the span from the first to the last weekly scrape that showed the posting, plus 7 days. It starts at the first scrape that showed the posting (often after it was posted) and ends when it stopped appearing, whatever the reason.")
          )
        ),
        bslib::card_body(
          fillable = FALSE,
          htmltools::div(class = "trends-table-container mt-0",
              shinycssloaders::withSpinner(DT::DTOutput("k12_spell_table", fill = FALSE)))
        )
      )
    ),
    spells_footnote()
  )
}

